<?php
session_start();
require_once __DIR__.'/../config/config.php';
if(empty($_SESSION['user_id'])){header('Location:login.php');exit;}
$userId=(int)$_SESSION['user_id'];$role=$_SESSION['role']??'';
if(!in_array($role,['publisher_admin','shop_admin'],true)){header('Location:home.php');exit;}
if($role==='publisher_admin'){$q=$pdo->prepare('SELECT p.company_name name FROM publisher_staff ps JOIN publishers p ON p.publisher_id=ps.publisher_id WHERE ps.user_id=? LIMIT 1');}
else{$q=$pdo->prepare('SELECT s.shop_name name FROM shop_staff ss JOIN shops s ON s.shop_id=ss.shop_id WHERE ss.user_id=? LIMIT 1');}
$q->execute([$userId]);$seller_name=(string)($q->fetchColumn()?:'');$active_menu='notifications';
if(empty($_SESSION['admin_notifications_csrf']))$_SESSION['admin_notifications_csrf']=bin2hex(random_bytes(24));
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['admin_notifications_csrf'],(string)($_POST['csrf_token']??''))){http_response_code(403);exit('คำขอไม่ถูกต้อง');}
 $action=(string)($_POST['action']??'');
 if($action==='read_all')$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$userId]);
 elseif($action==='delete_all')$pdo->prepare('DELETE FROM notifications WHERE user_id=?')->execute([$userId]);
 elseif($action==='delete_one')$pdo->prepare('DELETE FROM notifications WHERE notification_id=? AND user_id=?')->execute([(int)($_POST['notification_id']??0),$userId]);
 header('Location:admin_notifications.php');exit;
}
if(isset($_GET['read'])){
 $id=(int)$_GET['read'];$q=$pdo->prepare('SELECT * FROM notifications WHERE notification_id=? AND user_id=?');$q->execute([$id,$userId]);$notice=$q->fetch(PDO::FETCH_ASSOC);
 if($notice){$pdo->prepare('UPDATE notifications SET is_read=1 WHERE notification_id=?')->execute([$id]);if($notice['notification_type']==='review'){header('Location:/pages/seller_review_management.php'.(!empty($notice['related_review_id'])?'#review-'.(int)$notice['related_review_id']:''));exit;}if($notice['notification_type']==='chat'){$conversation=(int)($notice['chat_conversation_id']??0);header('Location:admin_chat.php'.($conversation?'?conversation='.$conversation:''));exit;}if(preg_match('/#(WN\d+)/',$notice['message'],$m)){header('Location:admin_orders.php?order='.urlencode($m[1]));exit;}}
 header('Location:admin_notifications.php');exit;
}
$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 80');$q->execute([$userId]);$notices=$q->fetchAll(PDO::FETCH_ASSOC);
ob_start(function(string $html) use($notices):string{
 $csrf=json_encode($_SESSION['admin_notifications_csrf'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
 $extra='<style>.notification-actions{display:flex;gap:10px;flex-wrap:wrap;margin:-14px 0 24px}.notification-action,.notice-delete{border:1px solid #d18aa7;border-radius:9px;padding:9px 14px;background:#fff;color:#a74e70;font:inherit;cursor:pointer}.notification-action.primary{background:#d18aa7;color:#fff}.notice-delete{padding:7px 11px;border-color:#e3b7c5;color:#b83e4b}.notice-link{display:contents}.notice{grid-template-columns:48px minmax(0,1fr) auto auto}@media(max-width:750px){.notice{grid-template-columns:42px minmax(0,1fr) auto}.notice-delete{grid-column:3;grid-row:1/3}.notification-actions{margin-top:-12px}}</style><script>document.addEventListener("DOMContentLoaded",()=>{const csrf='.$csrf.';const main=document.querySelector("main.main"),heading=main?.querySelector("h1");if(!main||!heading)return;const submit=(action,id=0)=>{const form=document.createElement("form");form.method="post";form.hidden=true;for(const [name,value] of Object.entries({csrf_token:csrf,action,notification_id:id})){const input=document.createElement("input");input.name=name;input.value=value;form.append(input)}document.body.append(form);form.submit()};const bar=document.createElement("div");bar.className="notification-actions";const read=document.createElement("button");read.type="button";read.className="notification-action primary";read.textContent="อ่านทั้งหมด";read.onclick=()=>submit("read_all");const clear=document.createElement("button");clear.type="button";clear.className="notification-action";clear.textContent="ลบทั้งหมด";clear.onclick=()=>{if(confirm("ต้องการลบการแจ้งเตือนทั้งหมดใช่หรือไม่? การดำเนินการนี้ไม่สามารถย้อนกลับได้"))submit("delete_all")};bar.append(read,clear);heading.after(bar);main.querySelectorAll("a.notice").forEach(link=>{const id=Number(new URL(link.href,location.href).searchParams.get("read"));const card=document.createElement("article");card.className=link.className;const open=document.createElement("a");open.className="notice-link";open.href=link.href;while(link.firstChild)open.append(link.firstChild);const del=document.createElement("button");del.type="button";del.className="notice-delete";del.textContent="ลบ";del.setAttribute("aria-label","ลบการแจ้งเตือนนี้");del.onclick=()=>submit("delete_one",id);card.append(open,del);link.replaceWith(card)});});</script>';
 $iconData=[];
 foreach($notices as $notice){
  $kind=$notice['notification_type']??'general';
  if($kind==='order'){
   $text=($notice['title']??'').' '.($notice['message']??'');
   $kind=preg_match('/สลิป|ชำระ|ตรวจสอบ/u',$text)?'payment':(preg_match('/จัดส่ง|พัสดุ|ขนส่ง/u',$text)?'shipping':'order');
  }
  $iconData[(int)$notice['notification_id']]=$kind;
 }
 $iconsScript='<style>.icon svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.notice[data-kind="chat"] .icon{background:#f6dfeb;color:#ad5277}.notice[data-kind="order"] .icon{background:#e5f1eb;color:#39715a}.notice[data-kind="payment"] .icon{background:#fff0d9;color:#a96c22}.notice[data-kind="shipping"] .icon{background:#e4eef8;color:#3f6f9d}.notice[data-kind="exchange"] .icon{background:#e3f2f3;color:#28727d}.notice[data-kind="follow"] .icon{background:#eee6f8;color:#7754a2}</style><script>document.addEventListener("DOMContentLoaded",()=>{const kinds='.json_encode($iconData,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).';const icons={chat:`<svg viewBox="0 0 24 24"><path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"/></svg>`,order:`<svg viewBox="0 0 24 24"><path d="M6 8h12l1 13H5z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg>`,payment:`<svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/></svg>`,shipping:`<svg viewBox="0 0 24 24"><path d="M3 6h11v11H3zM14 10h4l3 3v4h-7z"/><circle cx="7" cy="19" r="2"/><circle cx="18" cy="19" r="2"/></svg>`,exchange:`<svg viewBox="0 0 24 24"><path d="M4 7h14M15 4l3 3-3 3M20 17H6M9 14l-3 3 3 3"/></svg>`,follow:`<svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="4"/><path d="M2 21a7 7 0 0 1 14 0M19 8v6M16 11h6"/></svg>`,general:`<svg viewBox="0 0 24 24"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>`};document.querySelectorAll("article.notice").forEach(card=>{const link=card.querySelector("a[href*=read]");const id=Number(new URL(link.href,location.href).searchParams.get("read")),kind=kinds[id]||"general";card.dataset.kind=kind;const icon=card.querySelector(".icon");if(icon)icon.innerHTML=icons[kind]||icons.general});});</script>';
 $liveListScript='<script>document.addEventListener("DOMContentLoaded",()=>{const csrf='.$csrf.';const main=document.querySelector("main.main");if(!main)return;const sendDelete=id=>{const form=document.createElement("form");form.method="post";form.hidden=true;for(const [name,value] of Object.entries({csrf_token:csrf,action:"delete_one",notification_id:id})){const input=document.createElement("input");input.name=name;input.value=value;form.append(input)}document.body.append(form);form.submit()};const chatIcon=`<svg viewBox="0 0 24 24"><path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"/></svg>`;document.addEventListener("wanawan:notification",event=>{const notice=event.detail;if(!notice||main.querySelector(`[data-notification-id="${notice.id}"]`))return;main.querySelector(".empty")?.remove();const card=document.createElement("article");card.className="notice unread";card.dataset.kind=notice.type||"general";card.dataset.notificationId=String(notice.id);const open=document.createElement("a");open.className="notice-link";open.href=notice.url;const icon=document.createElement("span");icon.className="icon";icon.innerHTML=chatIcon;const copy=document.createElement("span"),title=document.createElement("h2"),message=document.createElement("p");title.textContent=notice.title;message.textContent=notice.message;copy.append(title,message);const time=document.createElement("span");time.className="time";time.textContent=`วันนี้ ${notice.time} `;const dot=document.createElement("i");dot.className="dot";time.append(dot);open.append(icon,copy,time);const del=document.createElement("button");del.type="button";del.className="notice-delete";del.textContent="ลบ";del.onclick=()=>sendDelete(notice.id);card.append(open,del);const actions=main.querySelector(".notification-actions");if(actions)actions.after(card);else main.querySelector("h1")?.after(card)});});</script>';
 $initialId=$notices?max(array_map(fn($notice)=>(int)$notice['notification_id'],$notices)):0;
 $extra='<script>window.wanawanNotificationInitialId='.(int)$initialId.';</script><style>.notice-link{color:inherit;text-decoration:none}</style>'.$extra.$iconsScript.$liveListScript;
 return str_replace('</body>',$extra.'</body>',$html);
});
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>การแจ้งเตือนหลังบ้าน - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css"><style>
*{box-sizing:border-box;margin:0;padding:0}body{font-family:var(--font-family);background:#fff;display:flex;min-height:100vh}.sidebar{width:260px;min-height:100vh;background:#f9e1eb;display:flex;flex-direction:column;padding:25px 16px;position:fixed}.sidebar-logo{display:flex;align-items:center;gap:10px;padding:0 12px 30px}.sidebar-logo img{width:74px}.sidebar-logo-text{font-size:24px;color:var(--secondary-color);font-weight:700}.sidebar-logo-sub,.profile-role{font-size:11px;color:var(--primary-color)}.sidebar-nav{display:flex;flex-direction:column;gap:9px;flex:1}.nav-item{display:flex;align-items:center;gap:12px;padding:13px 15px;border-radius:8px;text-decoration:none;color:#91576d}.nav-item svg{width:20px;height:20px}.nav-item.active,.nav-item:hover{background:#d18aa7;color:#fff}.admin-order-badge{margin-left:auto;background:#c83232;color:#fff;border-radius:20px;padding:3px 7px;font-size:11px}.sidebar-profile{display:flex;gap:10px;align-items:center;padding:15px}.profile-avatar{width:40px;height:40px;border-radius:50%;background:#fff;display:grid;place-items:center;overflow:hidden}.profile-avatar img{width:100%;height:100%;object-fit:cover}.profile-seller,.profile-name{font-size:12px;font-weight:700}.main{margin-left:260px;padding:55px 45px;width:calc(100% - 260px)}h1{color:var(--secondary-color);margin-bottom:28px}.notice{display:grid;grid-template-columns:48px 1fr auto;gap:16px;align-items:center;padding:18px 20px;border:1px solid #e2c8d1;border-radius:12px;margin-bottom:11px;text-decoration:none;color:inherit;background:#fff}.notice.unread{background:#fff2f6;border-color:#d18aa7}.icon{width:44px;height:44px;border-radius:50%;background:#f4dbe4;display:grid;place-items:center;color:#a45472}.notice h2{font-size:17px;margin-bottom:5px}.notice p,.time{color:#827178;font-size:13px}.dot{width:9px;height:9px;border-radius:50%;background:#c83232;display:inline-block;margin-left:8px}.empty{text-align:center;padding:100px;color:#88777e}@media(max-width:750px){body{display:block}.sidebar{position:static;width:100%}.main{margin:0;width:100%;padding:30px 15px}.notice{grid-template-columns:42px 1fr}.time{grid-column:2}}
</style></head><body><?php include __DIR__.'/../components/sidebar.php';?><main class="main"><h1>การแจ้งเตือนหลังบ้าน</h1><?php if(!$notices):?><div class="empty">ยังไม่มีการแจ้งเตือน</div><?php else:foreach($notices as $n):?><a class="notice <?=$n['is_read']?'':'unread'?>" href="?read=<?=$n['notification_id']?>"><span class="icon"><?=$n['notification_type']==='order'?'▣':'●'?></span><span><h2><?=htmlspecialchars($n['title'])?></h2><p><?=htmlspecialchars($n['message'])?></p></span><span class="time"><?=htmlspecialchars($n['created_at'])?><?=$n['is_read']?'':'<i class="dot"></i>'?></span></a><?php endforeach;endif;?></main></body></html>
